/**
* Evaluates a polynomial having an arbitrary number of coefficients.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation and mirrors `@stdlib/math/base/tools/evalpoly`, including the short-circuit when `x` equals zero. The short-circuit must be retained, as, for half-integer reflection arguments, the evaluation point is exactly zero, and plain Horner evaluation could otherwise return NaN when provided non-finite coefficients.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param c      polynomial coefficients sorted in ascending degree
* @param len    number of coefficients
* @param x      value at which to evaluate the polynomial
* @return       evaluated polynomial
*/
static double evalpoly( const double *c, const int32_t len, const double x ) {
	int32_t i;
	double p;

	if ( len < 2 || x == 0.0 ) {
		return ( len == 0 ) ? 0.0 : c[ 0 ];
	}
	i = len - 1;
	p = ( c[ i ] * x ) + c[ i-1 ];
	i -= 2;
	while ( i >= 0 ) {
		p = ( p * x ) + c[ i ];
		i -= 1;
	}
	return p;
}

/**
* Evaluates the n'th derivative of `cot(πx)` at `x`.
*
* @param n     derivative to evaluate
* @param x     input value
* @param xc    one minus `x`
* @return      n'th derivative
*/
static double polycotpi( const int32_t n, const double x, const double xc ) {
	double powTerms;
	double *wsp;
	double *cur;
	double *nxt;
	double *tmp;
	double sum;
	double out;
	double s;
	double c;
	int32_t noffset; // offset for next row
	int32_t offset; // 1 if the first cos power is 0; otherwise 0
	int32_t ncols; // how many entries there are in the current row
	int32_t mcols; // how many entries there will be in the next row
	int32_t len;
	int32_t mo; // largest order of the polynomial of cos terms
	int32_t so; // order of the sin term
	int32_t co; // order of the cosine term in entry "j"
	int32_t i;
	int32_t j;
	int32_t k;

	// Use the argument having the smaller absolute value for improved accuracy (mathematically, `sinpi( x ) == sinpi( xc )`, as `x + xc == 1`):
	s = ( stdlib_base_abs( x ) < stdlib_base_abs( xc ) ) ? stdlib_base_sinpi( x ) : stdlib_base_sinpi( xc );
	c = stdlib_base_cospi( x );
	switch ( n ) {
	case 1:
		return -STDLIB_CONSTANT_FLOAT64_PI / ( s * s );
	case 2:
		return 2.0 * PI2 * c / stdlib_base_pow( s, 3.0 );
	case 3:
		return PI3 * polyval_p3( c * c ) / stdlib_base_pow( s, 4.0 );
	case 4:
		return PI4 * c * polyval_p4( c * c ) / stdlib_base_pow( s, 5.0 );
	case 5:
		return PI5 * polyval_p5( c * c ) / stdlib_base_pow( s, 6.0 );
	case 6:
		return PI6 * c * polyval_p6( c * c ) / stdlib_base_pow( s, 7.0 );
	case 7:
		return PI7 * polyval_p7( c * c ) / stdlib_base_pow( s, 8.0 );
	case 8:
		return PI8 * c * polyval_p8( c * c ) / stdlib_base_pow( s, 9.0 );
	case 9:
		return PI9 * polyval_p9( c * c ) / stdlib_base_pow( s, 10.0 );
	case 10:
		return PI10 * c * polyval_p10( c * c ) / stdlib_base_pow( s, 11.0 );
	case 11:
		return PI11 * polyval_p11( c * c ) / stdlib_base_pow( s, 12.0 );
	case 12:
		return PI12 * c * polyval_p12( c * c ) / stdlib_base_pow( s, 13.0 );
	default:
		break;
	}
	// We'll have to compute the coefficients up to `n`; however, if the final evaluation would have too many terms, just bail out right away:
	if ( ( (double)n / 2.0 ) > (double)MAX_SERIES_ITERATIONS ) {
		return 0.0 / 0.0; // NaN
	}
	/*
	* Compute the coefficients of the n'th derivative via the recurrence relation
	*
	*     C[k-1, m+1] -= k * C[k, m]
	*     C[k+1, m+1] += (k-m-1) * C[k, m]
	*
	* seeded with `C[0, 1] = -1`, where row `m` stores only the non-zero coefficients (every other term in the polynomials is zero, so row `m` stores the coefficient of `cos^(2j + (m-1)&1)` at index `j`).
	*
	* The JavaScript implementation lazily grows a module-level memoization table (and Boost, similarly, a vector of vectors). As the recurrence only ever reads row `i` when writing row `i+1`, we instead recompute the final row on each call using two heap-allocated "ping-pong" row buffers, which is bit-identical to evaluating a fully memoized table (the recurrence is deterministic) and differs only in performance. Heap allocation is required, as row lengths grow as `n/2` (given the semantic bound `n <= 2000000`, a row may hold ~10^6 doubles (~8 MB), which cannot be stack-allocated), and a mutable static workspace would not be thread-safe.
	*/
	len = ( ( n - 1 ) / 2 ) + 1; // length of the final row
	wsp = (double *)malloc( (size_t)( 2 * len ) * sizeof( double ) );
	if ( wsp == NULL ) {
		return 0.0 / 0.0; // NaN
	}
	cur = wsp;
	nxt = wsp + len;
	cur[ 0 ] = -1.0; // row 0 (first derivative): single coefficient `-1.0`

	// Build rows `1..n-1` (note: row `r` has length `floor(r/2)+1 <= len`, and reads of the current row (indices `0..ncols`) touch only entries written when that row was built, so uninitialized memory is never read):
	for ( i = 0; i < n - 1; i++ ) {
		offset = i & 1;
		so = i + 2;
		mo = so - 1;
		ncols = ( mo - offset ) / 2;
		noffset = ( offset ) ? 0 : 1;
		mcols = ( mo + 1 - noffset ) / 2;

		// Zero-fill the next row:
		for ( j = 0; j <= mcols; j++ ) {
			nxt[ j ] = 0.0;
		}
		for ( j = 0; j <= ncols; j++ ) {
			co = ( 2 * j ) + offset;
			k = ( co + 1 ) / 2;
			nxt[ k ] += ( (double)( co - so ) * cur[ j ] ) / (double)( so - 1 );
			if ( co != 0 ) {
				k = ( co - 1 ) / 2;
				nxt[ k ] += ( -(double)co * cur[ j ] ) / (double)( so - 1 );
			}
		}
		// Swap the row buffers:
		tmp = cur;
		cur = nxt;
		nxt = tmp;
	}
	sum = evalpoly( cur, len, c * c );
	free( wsp );
	if ( ( n - 1 ) & 1 ) {
		sum *= c; // the first coefficient is order 1, so the row is really an odd polynomial
	}
	if ( sum == 0.0 ) {
		return sum; // NOTE: may be either positive or negative zero
	}
	// The remaining terms are computed using logs since the powers and factorials get real large real quick:
	powTerms = (double)n * STDLIB_CONSTANT_FLOAT64_LN_PI;
	if ( s == 0.0 ) {
		return ( sum >= 0.0 ) ? STDLIB_CONSTANT_FLOAT64_PINF : STDLIB_CONSTANT_FLOAT64_NINF;
	}
	powTerms -= stdlib_base_ln( stdlib_base_abs( s ) ) * ( (double)n + 1.0 );
	powTerms += stdlib_base_gammaln( (double)n ) + stdlib_base_ln( stdlib_base_abs( sum ) );

	if ( powTerms > STDLIB_CONSTANT_FLOAT64_MAX_LN ) {
		return ( sum >= 0.0 ) ? STDLIB_CONSTANT_FLOAT64_PINF : STDLIB_CONSTANT_FLOAT64_NINF;
	}
	out = stdlib_base_exp( powTerms ) * stdlib_base_signum( sum );
	if ( s < 0.0 && ( ( n + 1 ) & 1 ) ) {
		out *= -1.0;
	}
	return out;
}

/**
* Evaluates the polygamma function for large values of `x` such as for `x > 400`.
*
* ## References
*
* -   [Wolfram Research: Series representations][@wolfram:polygamma2:series]
*
* [@wolfram:polygamma2:series]: http://functions.wolfram.com/GammaBetaErf/PolyGamma2/06/02/0001/
*
* @param n    derivative to evaluate
* @param x    input value
* @return     (n+1)'th derivative
*/
static double atinfinityplus( const int32_t n, const double x ) {
	double partTerm; // value of current term excluding the Bernoulli number part
	double xsquared;
	double term; // value of current term to be added to sum
	double sum; // current value of accumulated sum
	double nlx;
	double k2;
	int32_t k;

	if ( (double)n + x == x ) {
		// If `x` is very large, just concentrate on the first part of the expression and use logs:
		if ( n == 1 ) {
			// NOTE: while unreachable via the main dispatch function (which delegates `n == 1` to `stdlib_base_trigamma`), the following branch is retained for fidelity with the original (Boost) implementation:
			return 1.0 / x;
		}
		nlx = (double)n * stdlib_base_ln( x );
		if ( nlx < STDLIB_CONSTANT_FLOAT64_MAX_LN && n < MAX_FACTORIAL ) {
			return ( ( n & 1 ) ? 1.0 : -1.0 ) * stdlib_base_factorial( (double)n - 1.0 ) * stdlib_base_pow( x, -(double)n );
		}
		return ( ( n & 1 ) ? 1.0 : -1.0 ) * stdlib_base_exp( stdlib_base_gammaln( (double)n ) - ( (double)n * stdlib_base_ln( x ) ) );
	}
	xsquared = x * x;

	// Start by setting `partTerm` to `(n-1)! / x^(n+1)`, which is common to both the first term of the series (with k = 1) and to the leading part. We can then get to the leading term by: `partTerm * (n + 2 * x) / 2` and to the first term in the series (excluding the Bernoulli number) by: `partTerm n * (n + 1) / (2x)`. If either the factorial would over- or the power term underflow, set `partTerm` to 0 and then we know that we have to use logs for the initial terms:
	if ( n > MAX_FACTORIAL && ( (double)n * (double)n ) > STDLIB_CONSTANT_FLOAT64_MAX_LN ) {
		partTerm = 0.0;
	} else {
		partTerm = stdlib_base_factorial( (double)n - 1.0 ) * stdlib_base_pow( x, -(double)n - 1.0 );
	}
	if ( partTerm == 0.0 ) {
		// Either `n` is very large, or the power term underflows. Set the initial values of `partTerm`, `term`, and `sum` via logs:
		partTerm = stdlib_base_gammaln( (double)n ) - ( ( (double)n + 1.0 ) * stdlib_base_ln( x ) );
		sum = stdlib_base_exp( partTerm + stdlib_base_ln( (double)n + ( 2.0 * x ) ) - STDLIB_CONSTANT_FLOAT64_LN2 );
		partTerm += stdlib_base_ln( (double)n * ( (double)n + 1.0 ) ) - STDLIB_CONSTANT_FLOAT64_LN2 - stdlib_base_ln( x );
		partTerm = stdlib_base_exp( partTerm );
	} else {
		sum = partTerm * ( (double)n + ( 2.0 * x ) ) / 2.0;
		partTerm *= ( (double)n * ( (double)n + 1.0 ) ) / 2.0;
		partTerm /= x;
	}
	// If the leading term is 0, so is the result:
	if ( sum == 0.0 ) {
		return sum; // NOTE: the early return intentionally precedes the final parity adjustment and may thus return positive zero
	}
	for ( k = 1; ; ) {
		term = partTerm * stdlib_base_bernoulli( (double)( 2 * k ) );
		sum += term;

		// Normal termination condition:
		if ( stdlib_base_abs( term / sum ) < STDLIB_CONSTANT_FLOAT64_EPS ) {
			break;
		}
		// Increment our counter, and move `partTerm` on to the next value (note: the recurrence products must be computed in double-precision arithmetic, as the equivalent 32-bit integer products may overflow):
		k += 1;
		k2 = 2.0 * (double)k;
		partTerm *= ( (double)n + k2 - 2.0 ) * ( (double)n - 1.0 + k2 );
		partTerm /= ( k2 - 1.0 ) * k2;
		partTerm /= xsquared;
		if ( k > MAX_SERIES_ITERATIONS ) {
			return 0.0 / 0.0; // NaN
		}
	}
	if ( ( n - 1 ) & 1 ) {
		sum = -sum;
	}
	return sum;
}

/**
* Evaluates the polygamma function for intermediate values of `x` by performing a forward recursion into the asymptotic (large `x`) regime.
*
* ## References
*
* -   [Wolfram Research: Recurrence identities][@wolfram:polygamma2:recurrence]
*
* [@wolfram:polygamma2:recurrence]: http://functions.wolfram.com/GammaBetaErf/PolyGamma2/16/01/01/0017/
*
* @param n    derivative to evaluate
* @param x    input value
* @return     (n+1)'th derivative
*/
static double attransitionplus( const int32_t n, const double x ) {
	double minusMminus1;
	double lnterm;
	double zpows;
	double iter;
	double sum0;
	double d4d;
	double N;
	double z;
	int32_t k;

	// Use N = (0.4 * digits) + (4 * n) for target value for x:
	d4d = 0.4 * DIGITS_BASE10;
	N = d4d + ( 4.0 * (double)n );

	// NOTE: `iter` is a double having a fractional part and may be NaN (when `x` is NaN); the loops below run exactly `floor(iter)` times (zero times for NaN), matching JavaScript semantics:
	iter = N - stdlib_base_trunc( x );

	if ( iter > (double)MAX_SERIES_ITERATIONS ) {
		return 0.0 / 0.0; // NaN
	}
	minusMminus1 = -(double)n - 1.0;
	z = x;
	sum0 = 0.0;

	// cppcheck-suppress unreadVariable
	zpows = 0.0; // NOTE: dead initialization, kept to mirror the JavaScript implementation

	// Forward recursion to larger `x`, need to check for overflow first though:
	if ( stdlib_base_ln( z + iter ) * minusMminus1 > -STDLIB_CONSTANT_FLOAT64_MAX_LN ) {
		for ( k = 1; (double)k <= iter; k++ ) {
			zpows = stdlib_base_pow( z, minusMminus1 );
			sum0 += zpows;
			z += 1.0;
		}
		sum0 *= stdlib_base_factorial( (double)n );
	} else {
		for ( k = 1; (double)k <= iter; k++ ) {
			lnterm = ( stdlib_base_ln( z ) * minusMminus1 ) + stdlib_base_gammaln( (double)n + 1.0 );
			sum0 += stdlib_base_exp( lnterm );
			z += 1.0;
		}
	}
	if ( ( n - 1 ) & 1 ) {
		sum0 = -sum0;
	}
	return sum0 + atinfinityplus( n, z );
}

/**
* Evaluates the polygamma function near zero.
*
* ## Notes
*
* -   If we take this [expansion][1] for `polygamma` and substitute in this [expression][2] for `polygamma(n, 1)`, we get an alternating series for polygamma when `x` is small in terms of zeta functions of integer arguments (which are easy to evaluate, at least when the integer is even).
*
* [1]: http://functions.wolfram.com/06.15.06.0003.02
* [2]: http://functions.wolfram.com/06.15.03.0009.01
*
* @param n    derivative to evaluate
* @param x    input value
* @return     (n+1)'th derivative
*/
static double nearzero( const int32_t n, const double x ) {
	double factorialPart;
	double prefix;
	double scale;
	double term;
	double sum;
	int32_t k;

	// In order to avoid spurious overflow, save the `n!` term for later, and rescale at the end:
	scale = stdlib_base_factorial( (double)n );

	// "factorialPart" contains everything except the zeta function evaluations in each term:
	factorialPart = 1.0;

	// "prefix" is what we'll be adding the accumulated sum to, it will be `n! / z^(n+1)`, but since we're scaling by `n!` it is just `1 / z^(n+1)` for now:
	prefix = stdlib_base_pow( x, (double)n + 1.0 );
	if ( prefix == 0.0 ) {
		// NOTE: positive infinity is returned for all `n`, irrespective of parity (e.g., when `x` is `±0` or the power underflows), matching the JavaScript implementation:
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}
	prefix = 1.0 / prefix;

	// First term in the series is necessarily `< zeta(2) < 2`, so ignore the sum if it will have no effect on the result:
	if ( prefix > 2.0 / STDLIB_CONSTANT_FLOAT64_EPS ) {
		// NOTE: the JavaScript implementation wraps the following returns in overflow guards of the form `AX/prefix < scale ? ±infinity : ...`; however, as `AX` is an undefined (never assigned) variable there, the comparison is always false and the guards never fire. We reproduce the effective behavior (unguarded products), as natural IEEE 754 overflow to infinity coincides with the intended outcome:
		if ( n & 1 ) {
			return prefix * scale;
		}
		return -( prefix * scale );
	}
	sum = prefix;
	for ( k = 0; ; ) {
		// Get the k'th term (note: the argument sums must be computed in double-precision arithmetic, as the equivalent 32-bit integer sums may overflow):
		term = factorialPart * stdlib_base_zeta( (double)k + (double)n + 1.0 );
		sum += term;

		// Termination condition:
		if ( stdlib_base_abs( term ) < stdlib_base_abs( sum * STDLIB_CONSTANT_FLOAT64_EPS ) ) {
			break;
		}
		// Move on `k` and `factorialPart`:
		k += 1;
		factorialPart *= ( -x * ( (double)n + (double)k ) ) / (double)k;

		// Last chance exit:
		if ( k > MAX_SERIES_ITERATIONS ) {
			return 0.0 / 0.0; // NaN
		}
	}
	// We need to multiply by the scale, at each stage checking for overflow:
	if ( STDLIB_CONSTANT_FLOAT64_MAX / scale < sum ) {
		// NOTE: positive infinity is returned irrespective of parity (and also when `scale` is infinite, as `MAX` divided by infinity is `+0`), matching the JavaScript implementation:
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}
	sum *= scale;
	return ( n & 1 ) ? sum : -sum;
}

/**
* Evaluates the polygamma function.
*
* @param n    order of derivative
* @param x    input value
* @return     (n+1)'th derivative
*
* @example
* double out = stdlib_base_polygamma( 3, 1.2 );
* // returns ~3.245
*
* @example
* double out = stdlib_base_polygamma( 5, 1.2 );
* // returns ~41.39
*
* @example
* double out = stdlib_base_polygamma( 3, -4.9 );
* // returns ~60014.239
*
* @example
* double out = stdlib_base_polygamma( -1, 5.3 );
* // returns NaN
*
* @example
* double out = stdlib_base_polygamma( 2, -2.0 );
* // returns NaN
*
* @example
* double out = stdlib_base_polygamma( 1, 0.0 / 0.0 );
* // returns NaN
*/
double stdlib_base_polygamma( const int32_t n, const double x ) {
	double result;
	double limit;
	double z;
	double v;

	if ( n < 0 ) {
		// NOTE: the JavaScript implementation returns NaN for any `n` which is not a nonnegative integer; non-integer and NaN `n` are unrepresentable here, as, at the C/N-API boundary, `n` is an `int32_t` (the add-on truncates non-integer values and maps NaN to zero):
		return 0.0 / 0.0; // NaN
	}
	if ( n == 0 ) {
		return stdlib_base_digamma( x );
	}
	if ( n == 1 ) {
		return stdlib_base_trigamma( x );
	}
	if ( x < 0.0 ) {
		if ( stdlib_base_floor( x ) == x ) {
			// Result is infinity if `x` is an odd negative integer, and NaN (pole error) if `x` is an even negative integer. Parity is determined by halving the truncated value and comparing against its floor, which is equivalent to the JavaScript implementation's `trunc( x ) & 1` (ToInt32 wrapping preserves parity for every integer-valued double) for all inputs, including `x` equal to negative infinity, which is considered "even":
			v = stdlib_base_trunc( x ) / 2.0;
			if ( v != stdlib_base_floor( v ) ) {
				return STDLIB_CONSTANT_FLOAT64_PINF;
			}
			return 0.0 / 0.0; // NaN
		}
		z = 1.0 - x;
		result = stdlib_base_polygamma( n, z ) + ( STDLIB_CONSTANT_FLOAT64_PI * polycotpi( n, z, x ) );
		return ( n & 1 ) ? -result : result;
	}
	// Limit for use of small-x series is chosen so that the series doesn't go too divergent in the first few terms. Ordinarily, this would mean setting the limit to `~1/n`, but we can tolerate a small amount of divergence:
	limit = stdlib_base_min( 5.0 / (double)n, 0.25 );
	if ( x < limit ) {
		return nearzero( n, x );
	}
	if ( x > ( 0.4 * DIGITS_BASE10 ) + ( 4.0 * (double)n ) ) {
		return atinfinityplus( n, x );
	}
	if ( x == 1.0 ) {
		return ( ( n & 1 ) ? 1.0 : -1.0 ) * stdlib_base_factorial( (double)n ) * stdlib_base_zeta( (double)n + 1.0 );
	}
	if ( x == 0.5 ) {
		result = ( ( n & 1 ) ? 1.0 : -1.0 ) * stdlib_base_factorial( (double)n ) * stdlib_base_zeta( (double)n + 1.0 );
		if ( stdlib_base_abs( result ) >= stdlib_base_ldexp( STDLIB_CONSTANT_FLOAT64_MAX, -n - 1 ) ) {
			return ( stdlib_base_signum( result ) == 1.0 ) ? STDLIB_CONSTANT_FLOAT64_PINF : STDLIB_CONSTANT_FLOAT64_NINF;
		}
		// NOTE: the following line only executes when the previous guard failed, implying a finite factorial and, in turn, `n <= 170`, so `n+1` cannot overflow:
		result *= stdlib_base_ldexp( 1.0, n + 1 ) - 1.0;
		return result;
	}
	return attransitionplus( n, x );
}
